configs.forEach(add);['trout','btra','launch','access','contours','deep','noaa','lands','forest','wildlife','hap','parcels','county'].forEach(id=>$('layers').append(entries[id].row));map.on('zoomend',sync);sync();
$('legend').innerHTML='<div class="legend-items">'+[['#38a800','Type 1'],['#c5ac00','Type 2'],['#ed9300','Type 3'],['#005ce6','Type 4'],['#b777dc','Brook trout restoration'],['#888','Other / unclassified']].map(([c,t])=>`<div><i style="background:${c}"></i>${t}</div>`).join('')+'</div><p>Dashed streams: gear-restricted (GR). Colors are adapted for readability. Tap each stream for its full designation. Contours: brown 0–5, mustard 6–10, cyan 11–40, blue 41+ feet.</p>';
