const presets={fish:['trout','launch','access','deep','contours'],hunt:['lands','forest','wildlife','hap','parcels','county'],boat:['noaa','launch']};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{Object.values(entries).forEach(e=>e.on=presets[b.dataset.preset].includes(e.c.id));document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('selected',x===b));sync();});$('clear').onclick=()=>{Object.values(entries).forEach(e=>e.on=false);sync();};
